    /// <summary>
    /// OASIS provider for Push Protocol — Web3 notifications and messaging.
    /// Wallet addresses → Avatars. Notifications → Holons.
    /// API: https://api.push.org/apis/v1
    /// </summary>
    public class PushProtocolOASIS : OASISStorageProviderBase, IOASISStorageProvider, IOASISNETProvider
    {
        private readonly HttpClient _httpClient;
        private bool _isActivated;

        public PushProtocolOASIS(string apiBase = "https://api.push.org")
        {
            _httpClient = new HttpClient { BaseAddress = new Uri(apiBase) };
            _httpClient.DefaultRequestHeaders.Add("Accept", "application/json");
            ProviderName = "PushProtocolOASIS";
            ProviderDescription = "Push Protocol Web3 Notifications and Messaging Provider";
            ProviderType = new EnumValue<ProviderType>(Core.Enums.ProviderType.PushProtocolOASIS);
            ProviderCategory = new EnumValue<ProviderCategory>(Core.Enums.ProviderCategory.StorageAndNetwork);
            ProviderCategories.Add(new EnumValue<ProviderCategory>(Core.Enums.ProviderCategory.Network));
        }

        public override async Task<OASISResult<bool>> ActivateProviderAsync()
        {
            var result = new OASISResult<bool>();
            try
            {
                var response = await _httpClient.GetAsync("/apis/v1/users?caip10=eip155:1:0x0000000000000000000000000000000000000000&page=1&limit=1");
                if (response.IsSuccessStatusCode) { _isActivated = true; result.Result = true; result.Message = "PushProtocolOASIS activated."; }
                else OASISErrorHandling.HandleError(ref result, $"PushProtocolOASIS: API health check failed ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
        public override OASISResult<bool> ActivateProvider() => ActivateProviderAsync().Result;
        public override async Task<OASISResult<bool>> DeActivateProviderAsync() { _isActivated = false; return new OASISResult<bool>(true); }
        public override OASISResult<bool> DeActivateProvider() => DeActivateProviderAsync().Result;

        public override async Task<OASISResult<IAvatar>> LoadAvatarByProviderKeyAsync(string providerKey, int version = 0)
        {
            var result = new OASISResult<IAvatar>();
            try
            {
                var caip10 = providerKey.StartsWith("eip155:") ? providerKey : $"eip155:1:{providerKey}";
                var response = await _httpClient.GetAsync($"/apis/v1/users?caip10={caip10}");
                if (response.IsSuccessStatusCode)
                {
                    var body = await response.Content.ReadFromJsonAsync<JsonElement>();
                    var avatar = new Avatar();
                    avatar.Username = providerKey;
                    avatar.MetaData["push_caip10"] = caip10;
                    if (body.TryGetProperty("did", out var did)) avatar.MetaData["push_did"] = did.GetString();
                    if (body.TryGetProperty("wallets", out var wallets)) avatar.MetaData["push_wallets"] = wallets.ToString();
                    result.Result = avatar;
                }
                else OASISErrorHandling.HandleError(ref result, $"PushProtocolOASIS: User '{providerKey}' not found ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
        public override OASISResult<IAvatar> LoadAvatarByProviderKey(string providerKey, int version = 0) => LoadAvatarByProviderKeyAsync(providerKey, version).Result;

        public override async Task<OASISResult<IEnumerable<IHolon>>> LoadHolonsForParentAsync(string providerKey, HolonType type = HolonType.All, bool loadChildren = true, bool recursive = true, int maxChildDepth = 0, int curentChildDepth = 0, bool continueOnError = true, bool loadChildrenFromProvider = false, int version = 0)
        {
            var result = new OASISResult<IEnumerable<IHolon>>(); var holons = new List<IHolon>();
            try
            {
                var caip10 = providerKey.StartsWith("eip155:") ? providerKey : $"eip155:1:{providerKey}";
                var response = await _httpClient.GetAsync($"/apis/v1/users/{caip10}/feeds?page=1&limit=100&spam=false");
                if (response.IsSuccessStatusCode)
                {
                    var body = await response.Content.ReadFromJsonAsync<JsonElement>();
                    var feeds = body.TryGetProperty("feeds", out var f) ? f : body;
                    foreach (var feed in feeds.EnumerateArray())
                    {
                        var payload = feed.TryGetProperty("payload", out var p) ? p : feed;
                        var holon = new Holon();
                        holon.Name = payload.TryGetProperty("notification", out var n) && n.TryGetProperty("title", out var t) ? t.GetString() : "Push Notification";
                        holon.Description = payload.TryGetProperty("notification", out var n2) && n2.TryGetProperty("body", out var b) ? b.GetString() : "";
                        holon.MetaData["push_epoch"] = feed.TryGetProperty("epoch", out var e) ? e.GetString() : "";
                        holon.MetaData["push_sender"] = feed.TryGetProperty("sender", out var s) ? s.GetString() : "";
                        holons.Add(holon);
                    }
                    result.Result = holons;
                }
                else OASISErrorHandling.HandleError(ref result, $"PushProtocolOASIS: Get notifications failed ({response.StatusCode}).");
            }
            catch (Exception ex) { result.Exception = ex; OASISErrorHandling.HandleError(ref result, ex.Message); }
            return result;
        }
